"""
This module shall handle the mapping of hardware type
to the action to be performed to mirror the traffic
for the bip traces.
"""
import yaml
import os
from .tools import python_log


def read_config_file(file_name):
    assert os.path.exists(file_name), 'Config File {} does not exist!'
    with open(file_name, 'r') as stream:
        config_data = yaml.safe_load(stream)
        return config_data


def get_config_data(file_name):
    config_data = read_config_file(file_name)
    assert 'configs' in config_data, 'No Configs Section in Config Data!'
    return config_data['configs']


def item_contains_data(item, filter_data):
    return all(filter_data[key] == item.get(key) or item.get(key) == 'other'
               or item.get(key) == ['other']for key in filter_data)


def get_yaml_config_file():
    """
    Finds the yaml configuration within the installed python package
    """
    module_path, _ = os.path.split(os.path.realpath(__file__))
    config_script = os.path.join(module_path, 'mirror_scripts', 'config.yaml')
    if not os.path.exists(config_script):
        raise AssertionError("Configuration file [{}] not found!".format(config_script))
    return config_script


@python_log
def get_bip_script(l1_type, gnb_common_unit, gnb_capacity_unit):
    config_file = get_yaml_config_file()
    config_data = get_config_data(config_file)

    filter_data = {'L1_TYPE': l1_type,
                   'gNB_common_unit': gnb_common_unit,
                   'gNB_capacity_unit': gnb_capacity_unit}

    deal_config_data = []
    for L1_type, datas in config_data.items():
        for data in datas:
            data['L1_TYPE'] = L1_type
            deal_config_data.append(data)

    for item in deal_config_data:
        if item_contains_data(item, filter_data):
            return item['bip_script']
